 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    wall_rows = [r for r in range(h) if all(v == 2 for v in grid[r])]
    if not wall_rows:
        return [row[:] for row in grid]
    wall = wall_rows[0]
    direction = 1 if wall == 0 else -1  # motion away from a top wall, toward a bottom wall
    playable = [r for r in range(h) if r != wall]
    lo, hi = min(playable), max(playable)

    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            objects.append((color, cells))

    # Process objects closest to the solid boundary first.
    if direction == -1:
        objects.sort(key=lambda obj: min(r for r, c in obj[1]))
    else:
        objects.sort(key=lambda obj: max(r for r, c in obj[1]), reverse=True)

    occupied = set()
    settled = []
    for color, cells in objects:
        pos = list(cells)
        while True:
            nxt = [(r + direction, c) for r, c in pos]
            if any(r < lo or r > hi or (r, c) in occupied for r, c in nxt):
                break
            pos = nxt
        occupied.update(pos)
        settled.append((color, pos))

    out = [[0 for _ in range(w)] for _ in range(h)]
    out[wall] = [2] * w
    for color, cells in settled:
        for r, c in cells:
            out[r][c] = color
    return out
